<?php
// CLI only. Explicit isolated DSN; never reads the site's configuration.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$dsn=getenv('TEST_DSN');$user=getenv('TEST_DB_USER');$password=getenv('TEST_DB_PASS');$mode=isset($argv[1])?$argv[1]:'';
if(!is_string($dsn)||strpos($dsn,'mysql:')!==0||preg_match_all('/(?:^|;)\s*dbname\s*=/i',substr($dsn,6))!==1||!preg_match('/(?:^|;)dbname=(chaoxi_wallet_test_[A-Za-z0-9_]+)(?:;|$)/',substr($dsn,6),$match)||!in_array($mode,array('fresh','upgrade'),true))throw new RuntimeException('Explicit isolated TEST_DSN and fresh|upgrade required.');
$pdo=new PDO($dsn,$user,$password,array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC));
if($pdo->query('SELECT DATABASE()')->fetchColumn()!==$match[1])throw new RuntimeException('Database mismatch.');
if((int)$pdo->query('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()')->fetchColumn()!==0)throw new RuntimeException('Refusing nonempty test database.');
require __DIR__.'/migrate.php';
$root=dirname(__DIR__);
$assert=function($value,$message){if(!$value)throw new RuntimeException($message);echo "PASS ".$message."\n";};
// Fixed snapshot from 47e801d628f5756ae577a9961de6b1a56c3df880, not the runtime HEAD.
$oldSchema=base64_decode('');
$legacyFeedback=base64_decode('');
$before=array();
if($mode==='upgrade'){
 foreach(array_filter(array_map('trim',explode(';',$oldSchema.';'.$legacyFeedback))) as $sql)$pdo->exec($sql);
 $assert((int)$pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME='notifications' AND COLUMN_NAME='target_type') OR (TABLE_NAME='feedback_submissions' AND COLUMN_NAME='progress_status') OR (TABLE_NAME='support_tickets' AND COLUMN_NAME='version_no'))")->fetchColumn()===0,'actual legacy tables lack all service-center columns');
 $pdo->exec("INSERT INTO notifications(user_id,type,title,content,order_no,read_at,created_at) VALUES(41,'legacy','旧消息','保留原文','LEGACY-ORDER','2025-01-02 03:04:05','2025-01-01 01:02:03')");
 $pdo->exec("INSERT INTO support_tickets(ticket_no,user_id,subject,status,created_at,updated_at,closed_at) VALUES('LEGACY-TICKET',41,'旧工单','closed','2025-01-01 01:02:03','2025-01-02 03:04:05','2025-01-02 03:04:05')");
 $pdo->exec("INSERT INTO ticket_messages(ticket_id,sender_type,sender_user_id,body,created_at) VALUES(1,'user',41,'旧对话','2025-01-01 01:02:03')");
 $pdo->exec("INSERT INTO feedback_submissions(feedback_no,user_id,type,subject,body,status,reward_cents,admin_note,created_at,updated_at) VALUES('LEGACY-FEEDBACK',41,'suggestion','旧反馈','旧内容','rewarded',321,'原备注','2025-01-01 01:02:03','2025-01-02 03:04:05')");
 foreach(array('notifications','support_tickets','ticket_messages','feedback_submissions') as $table)$before[$table]=$pdo->query('SELECT * FROM '.$table)->fetchAll();
 // Deterministically interrupt after the first ALTER. MySQL DDL commits persist.
 $interrupt=new class($pdo){private $pdo;public function __construct($p){$this->pdo=$p;}public function prepare($s){return $this->pdo->prepare($s);}public function query($s){return $this->pdo->query($s);}public function exec($s){$r=$this->pdo->exec($s);if(strpos($s,'ALTER TABLE notifications ADD target_type')===0)throw new RuntimeException('simulated_interruption');return $r;}};
 try{run_migrations($interrupt,$root);throw new RuntimeException('Expected interruption missing.');}catch(RuntimeException $e){if($e->getMessage()!=='simulated_interruption')throw $e;}
 $assert((int)$pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND COLUMN_NAME='target_type'")->fetchColumn()===1,'interrupted migration retained completed ALTER');
}
run_migrations($pdo,$root);run_migrations($pdo,$root);
foreach($before as $table=>$rows){$after=$pdo->query('SELECT * FROM '.$table)->fetchAll();$projected=array();foreach($after as $row)$projected[]=array_intersect_key($row,$rows[0]);$assert($projected===$rows,'legacy '.$table.' fields unchanged after upgrade and rerun');}
$assert((int)$pdo->query('SELECT COUNT(*) FROM feedback_progress_events')->fetchColumn()===0,'no fabricated progress history');
$assert((int)$pdo->query('SELECT COUNT(*) FROM feedback_submissions WHERE progress_status IS NOT NULL OR progress_updated_at IS NOT NULL OR progress_version<>0')->fetchColumn()===0,'legacy progress remains null/version zero');
foreach(array('announcements','ticket_operations','feedback_progress_events') as $table)$assert((int)$pdo->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='".$table."'")->fetchColumn()===1,$table.' exists');
$pdo->exec("INSERT INTO notifications(user_id,type,title,content,dedupe_key,created_at) VALUES(99,'test','t','c','same-event',NOW())");
try{$pdo->exec("INSERT INTO notifications(user_id,type,title,content,dedupe_key,created_at) VALUES(99,'test','t','c','same-event',NOW())");throw new RuntimeException('Dedupe unique index missing.');}catch(PDOException $e){$assert((int)$e->errorInfo[1]===1062,'notification event uniqueness enforced');}
echo 'PASS '.$mode.' migration on '.$match[1]."\n";
